using System;using System.Linq;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
// Reports are built from calculation records, never from clipped console columns.
static class TakeoffEngineeringReports {
 static string N(double value){return value.ToString("0.###",CultureInfo.InvariantCulture);}
 static string Source(EstimateInput entry){return entry.Description+" / "+entry.Beam+" · Qty "+entry.Quantity;}
 static EngineeringReport New(string title,ProjectInformation p,string mode){var report=ProfessionalReport.Create(title,p.Name,p.Location,p.Office);report.Subtitle=mode+" · Quantity take-off and calculation backup";return report;}
 static void Steel(EngineeringReport report,IEnumerable<EstimateInput> entries,List<StockAllocation> plan,bool detailed){
  var valid=plan.Where(a=>a.Choice!=null).ToList();var section=report.Section("Reinforcing steel purchase summary");section.Note("Purchased quantities include allocated splice steel and stock offcuts. Source allocations explain the same purchase total; do not add them again. Compatible cuts share stock; grades and diameters remain separate. Kerf = 0.");
  section.Table(new[]{"Material","Net steel kg","Purchase kg"},valid.GroupBy(a=>new{a.Demand.Grade,a.Demand.Diameter}).OrderBy(g=>g.Key.Grade).ThenBy(g=>g.Key.Diameter).Select(g=>new[]{"Grade "+g.Key.Grade+" / Ø"+g.Key.Diameter+" mm",N(g.Sum(a=>a.Net)),N(g.Sum(a=>a.Purchase))}));
  section.Table(new[]{"Source / member","Net steel kg","Purchase kg"},entries.Where(e=>e.Result!=null).Select(e=>new[]{Source(e),N(valid.Where(a=>a.Entry==e).Sum(a=>a.Net)),N(valid.Where(a=>a.Entry==e).Sum(a=>a.Purchase))}));
  section.Paragraph("Total rebar to purchase = "+N(valid.Sum(a=>a.Purchase))+" kg.");
  var stocks=valid.SelectMany(a=>a.Stocks).Distinct().ToList();if(stocks.Count>0)report.Section("Commercial bars to order").Table(new[]{"Grade / diameter / stock length","Whole bars","Purchase kg"},stocks.GroupBy(s=>new{s.Grade,s.Diameter,s.Length}).OrderBy(g=>g.Key.Grade).ThenBy(g=>g.Key.Diameter).ThenBy(g=>g.Key.Length).Select(g=>new[]{"G"+g.Key.Grade+" / Ø"+g.Key.Diameter+" mm / "+N(g.Key.Length)+" m",g.Sum(s=>s.Count).ToString(CultureInfo.InvariantCulture),N(g.Sum(s=>s.Length*s.Count*EstimatorEngine.UnitMass(s.Diameter)))}));
  if(plan.Any(a=>a.Choice==null)){report.Status="Partial — review unresolved cuts";section.Note("Some cuts cannot be allocated to the selected commercial lengths. Resolve them before issuing purchase quantities.");}
  if(detailed)foreach(var entry in entries.Where(e=>e.Result!=null)){var detail=report.Section("Rebar calculation / "+Source(entry));detail.Table(new[]{"Component / bar","Net kg","Purchase kg","Calculation / basis"},plan.Where(a=>a.Entry==entry).Select(a=>new[]{a.Line.Part+" / G"+a.Demand.Grade+" Ø"+a.Demand.Diameter+" mm",N(a.Net),a.Choice==null?"Unresolved":N(a.Purchase),(a.Line.Formula??"")+"; cut demand "+a.Demand.Pieces+" × "+N(a.Demand.Cut)+" m; added lap "+N(a.Splice)+" kg; allocated offcut "+N(a.Waste)+" kg."}));foreach(string note in entry.Result.Notes)detail.Note(note);}
 }
 internal static EngineeringReport Beams(ProjectInformation project,IEnumerable<EstimateInput> source,List<StockAllocation> plan,string mode,bool detailed){var entries=source.ToList();var report=New("Beam quantities and reinforcement",project,mode);var summary=report.Section("Concrete and formwork");summary.Equation("V = B × D × L × quantity\nAside = 2 × D × L × quantity\nAbottom = B × L × quantity for Elevated; 0 for On Fill.");summary.Table(new[]{"Member / location and input basis","Concrete m3","Formwork m2"},entries.Where(e=>e.Measures!=null).Select(e=>new[]{Source(e)+" · "+BeamSupportInput.Normalize(e.Support)+" · L="+e.Length+" m · B="+(e.Source==null?"?":e.Source.Cell(0))+" mm · D="+(e.Source==null?"?":e.Source.Cell(1))+" mm",N(e.Measures.Concrete),N(e.Measures.Formwork)}));summary.Paragraph("Total concrete = "+N(entries.Where(e=>e.Measures!=null).Sum(e=>e.Measures.Concrete))+" m3; total formwork = "+N(entries.Where(e=>e.Measures!=null).Sum(e=>e.Measures.Formwork))+" m2.");
  var ground=entries.Where(e=>e.Earthworks!=null).ToList();if(ground.Count>0){var earth=report.Section("Beam earthworks and gravel");earth.Note("Rectangular trenches; exclude overlapping pits/trenches. Bank, compacted and loose volumes have different bases. Soil balance here is per entry; the overall POW applies the shared project balance.");var rows=new List<string[]>();foreach(var e in ground){var q=e.Earthworks;rows.Add(new[]{Source(e)+" / excavation",N(q.Excavation),"bank m3",N(q.Width)+" m trench width × "+N(q.Depth)+" m depth × "+e.Length+" m × "+e.Quantity});rows.Add(new[]{Source(e)+" / gravel",N(q.Gravel),"m3","Beam width × 0.10 m gravel thickness × length × quantity"});rows.Add(new[]{Source(e)+" / backfill space",N(q.Backfill),"compacted m3",N(q.Excavation)+" excavation − "+N(q.Concrete)+" beam − "+N(q.Gravel)+" gravel − "+N(q.OtherConcrete)+" other buried concrete"});rows.Add(new[]{Source(e)+" / embankment",N(q.LooseRequired),"loose m3",N(q.Backfill)+" / (1 − "+N(q.Shrink)+"/100) × (1 + "+N(q.Swell)+"/100)"});}earth.Table(new[]{"Source / quantity","Quantity","Unit","Calculation / basis"},rows);}
  Steel(report,entries,plan,detailed);foreach(var e in entries.Where(e=>e.Result==null||e.Measures==null)){report.Status="Partial — review incomplete inputs";report.Section("Input requiring review / "+Source(e)).Note((e.Error??"")+" "+(e.MeasureError??""));}return report;
 }
 internal static EngineeringReport Slabs(ProjectInformation project,IEnumerable<SlabTakeoff> source,List<StockAllocation> plan,string mode,bool detailed,IEnumerable<string> errors){var entries=source.ToList();var report=New("Slab quantities and reinforcement",project,mode);var summary=report.Section("Concrete and formwork");summary.Equation("V = panel area × thickness × panel quantity\nFormwork = soffit forms + selected exposed-edge forms.");summary.Table(new[]{"Panel / location and input basis","Concrete m3","Formwork m2"},entries.Select(e=>new[]{Source(e.Steel)+" · "+e.GeometryBasis+" · thickness "+N(e.Thickness)+" mm",N(e.Measures.ConcreteTotal),N(e.Measures.FormworkTotal)}));summary.Paragraph("Total concrete = "+N(entries.Sum(e=>e.Measures.ConcreteTotal))+" m3; total formwork = "+N(entries.Sum(e=>e.Measures.FormworkTotal))+" m2.");Steel(report,entries.Select(e=>e.Steel),plan,detailed);foreach(string error in errors){report.Status="Partial — review incomplete inputs";report.Section("Input requiring review").Note(error);}return report;}
}
partial class EstimatorForm {internal EngineeringReport BuildEngineeringReport(){beams.EndEdit();Recalculate();return TakeoffEngineeringReports.Beams(ProjectInfoStore.Read(),inputs,CommercialBars.Allocate(inputs,lengthProfile,stockLengths),reportMode.Text,reportMode.SelectedIndex>0);}}
partial class SlabEstimatorForm {internal EngineeringReport BuildEngineeringReport(){grid.EndEdit();Recalculate();return TakeoffEngineeringReports.Slabs(ProjectInfoStore.Read(),results,currentPlan,mode.Text,mode.SelectedIndex>0,errors);}}
}
